    gallery_eyebrow: 'भीतर की एक झलक', gallery_h2: 'iPhone के लिए नेटिव। डिज़ाइन में सरल।', gallery_sub: 'देखने के लिए खींचें, स्क्रॉल करें या टैप करें',
